import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, float, mix, smoothstep, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const T = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DataTexture, DirectionalLight, Color } = T;

  const root = new Group();
  root.name = config.id || 'photo-hero-composite';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const cBg = new Color(colors.background || '#0b0b10');
  const cSurface = new Color(colors.surface || '#16161d');
  const cPaper = new Color(colors.paper || '#e8ecf2');
  const cAccent = new Color(colors.accent || '#ff2a38');

  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- placeholder texture helper ----
  function placeholder(r, g, b) {
    const d = new Uint8Array([r, g, b, 255]);
    const t = new DataTexture(d, 1, 1);
    t.needsUpdate = true;
    disposables.push(t);
    return t;
  }

  // ---- STAGE backdrop (vertical gradient) ----
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial();
  backMat.colorNode = mix(
    vec3(cBg.r, cBg.g, cBg.b),
    vec3(cSurface.r, cSurface.g, cSurface.b),
    uv().y
  );
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backGeo, backMat);

  // ---- lights (node-local rim + soft key) ----
  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(2.5, 3, 4);
  root.add(key);
  const rim = new DirectionalLight(cAccent.getHex(), 0.8);
  rim.position.set(-3, 1.2, 2.5);
  root.add(rim);

  // ---- PHOTO PLATE (displacement + filmic grade) ----
  const plateGeo = new PlaneGeometry(4.0, 2.5, 64, 64);
  const plateMat = new MeshBasicNodeMaterial();
  plateMat.transparent = true;

  const phColor = placeholder(20, 20, 26);
  const phDepth = placeholder(0, 0, 0);
  const colorTex = texture(phColor, uv());
  const depthTex = texture(phDepth, uv());

  // filmic grade: lift blacks -> #0d0d12, highlights -> #e8ecf2, +12% contrast, -8% desat (red preserved)
  const liftB = vec3(0.051, 0.051, 0.0706);
  const highW = vec3(cPaper.r, cPaper.g, cPaper.b);
  const graded = liftB.add(colorTex.rgb.mul(highW.sub(liftB)));
  const contrasted = graded.sub(0.5).mul(1.12).add(0.5);
  const lum = contrasted.r.mul(0.299)
    .add(contrasted.g.mul(0.587))
    .add(contrasted.b.mul(0.114));
  const desat = mix(contrasted, vec3(lum), float(0.08));
  plateMat.colorNode = vec3(contrasted.r, desat.g, desat.b);

  const plateOpacity = uniform(0.0);
  plateMat.opacityNode = plateOpacity;

  // depth displacement amplitude 0.18
  plateMat.positionNode = positionLocal.add(vec3(0, 0, depthTex.r.mul(0.18)));

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // ---- bottom scrim gradient ----
  const scrimGeo = new PlaneGeometry(4.0, 2.5);
  const scrimMat = new MeshBasicNodeMaterial();
  scrimMat.transparent = true;
  scrimMat.colorNode = vec3(cBg.r, cBg.g, cBg.b);
  scrimMat.opacityNode = smoothstep(0.55, 0.0, uv().y).mul(0.92);
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, 0, 0.22);
  root.add(scrim);
  disposables.push(scrimGeo, scrimMat);

  // ---- async texture loads ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex.value = tex;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex.value = tex;
    }).catch(() => {});
  }

  // ---- caption block (bottom-left, 0.5 padding) ----
  const caption = new Group();
  caption.position.set(0, 0, 0.3);
  root.add(caption);

  const leftX = -1.5;
  const TS = 0.01; // fontSize(px) -> scene-unit em height

  const items = config.textContent ?? spec.textContent ?? [];
  function copyFor(role, fallback) {
    const it = items.find((i) => i.role === role);
    return it && typeof it.text === 'string' ? it.text : fallback;
  }

  function addText(str, opts, y) {
    const t = ctx.fontAtlas.createText(str, opts);
    t.scale.setScalar(TS);
    t.position.set(leftX, y, 0);
    caption.add(t);
    disposables.push(t);
    return t;
  }

  addText(copyFor('kicker', 'NOVA ATELIER / GENEVA'), {
    fontSize: 9, color: '#ff2a38', align: 'left', letterSpacingPx: 1.1
  }, 0.25);

  addText(copyFor('headline', 'Time, Machined.'), {
    fontSize: 34, color: '#e8ecf2', align: 'left'
  }, -0.02);

  // accent hairline bar between headline and body
  const barGeo = new BoxGeometry(0.75, 0.02, 0.02);
  const barMat = new MeshStandardNodeMaterial();
  barMat.color = new Color('#000000');
  barMat.roughness = 0.5;
  barMat.metalness = 0.2;
  barMat.emissiveNode = vec3(cAccent.r, cAccent.g, cAccent.b).mul(1.8);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(leftX + 0.375, -0.33, 0.01);
  caption.add(bar);
  disposables.push(barGeo, barMat);

  addText(copyFor('body', 'Every case begins as a single billet of 904L steel.'), {
    fontSize: 13, color: '#e8ecf2', align: 'left', maxWidthPx: 340
  }, -0.5);

  addText(copyFor('caption', 'CALIBRE NA-01 / 72 HOUR RESERVE'), {
    fontSize: 9, color: '#e8ecf2', align: 'left', letterSpacingPx: 1.1
  }, -0.9);

  // ---- entrance motion ----
  const introTl = gsap.timeline();
  introTl.to(plateOpacity, {
    value: 1,
    duration: 0.5,
    ease: 'power2.out'
  });
  caption.position.y = 0.4;
  introTl.fromTo(caption.position,
    { y: 0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0.12
  );
  timelines.push(introTl);

  // subtle idle breathing (<=2%)
  const idleTl = gsap.to(plate.scale, {
    x: 1.012, y: 1.012,
    duration: 3.2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1
  });
  timelines.push(idleTl);

  // ---- cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = p && p.name ? ctx.primitives[p.name] : null;
    if (typeof fn === 'function') {
      try {
        const h = fn(plate, p.params || {});
        if (h) primHandles.push(h);
      } catch (e) { /* primitive noop */ }
    }
  }

  // ---- handlers / cleanup ----
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill && tl.kill());
    primHandles.forEach((h) => { try { h.cleanup && h.cleanup(); } catch (e) {} });
    disposables.forEach((d) => {
      if (!d) return;
      if (d.geometry) { try { d.geometry.dispose(); } catch (e) {} }
      if (d.material) { try { d.material.dispose(); } catch (e) {} }
      if (d.dispose) { try { d.dispose(); } catch (e) {} }
      if (d.traverse) {
        d.traverse((o) => {
          if (o.geometry) o.geometry.dispose();
          if (o.material) o.material.dispose();
        });
      }
    });
  };

  return root;
}
